// One knot from knots.txt: its photo, its name and what it is for
class Knot
{
    public string Picture { get; set; }   // the photo's file name
    public string Name { get; set; }      // the knot's name
    public string Use { get; set; }       // what the knot is for

    // Makes one Knot from a line of knots.txt, split at each |
    public Knot(string[] parts)
    {
        Picture = parts[0];
        Name = parts[1];
        Use = parts[2];
    }

    // Reads every knot in knots.txt into a list
    public static List<Knot> LoadAll()
    {
        List<Knot> knots = new List<Knot>();
        string path = Files.Data("knots.txt");
        if (!File.Exists(path)) return knots;   // no file: an empty list
        StreamReader reader = new StreamReader(path);
        while (!reader.EndOfStream)
        {
            string line = reader.ReadLine();
            string[] parts = line.Split('|');
            if (parts.Length != 3) continue;    // skip a broken line
            knots.Add(new Knot(parts));
        }
        reader.Close();
        return knots;
    }

// ---------- the game-form fields from chapter 9 ----------
private int gameNumber = 1;      // Knot Pairs is place 1 (0 is first)
private GameResult result;       // made when the round ends
private bool finished = false;   // true once the result is kept

// ---------- the game-form methods from chapter 9 ----------

// Keeps the result on the map, even if the window is then closed
private void KeepResult()
{
    Expedition.Finish(gameNumber, result);
    finished = true;
    lblScore.Text = "Points: " + result.Score;
}

// Fills in the Round over panel and brings it to the front
private void ShowRoundOver()
{
    lblRoundScore.Text = "You scored " + result.Score
        + " out of 100 points.";
    lblWellList.Text = ListText(result.WentWell,
        "thing that went well", "things that went well");
    lblWrongList.Text = ListText(result.WentWrong,
        "thing that went wrong", "things that went wrong");
    if (result.Score >= 60) Sound.Play("win.wav");
    else Sound.Play("lose.wav");
    pnlRoundOver.Visible = true;
    pnlRoundOver.BringToFront();
}

// Up to 3 lines from a list, then how many more there are
private string ListText(List<string> lines, string one, string many)
{
    if (lines.Count == 0) return "Nothing this time.";
    string text = "";
    for (int i = 0; i < lines.Count && i < 3; i++)
    {
        text = text + "- " + lines[i] + Environment.NewLine;
    }
    int more = lines.Count - 3;
    if (more == 1) text = text + "And 1 more " + one + ".";
    if (more > 1) text = text + "And " + more + " more " + many + ".";
    return text;
}

// Back to the map: closing the window runs FormClosing
private void btnBack_Click(object sender, EventArgs e)
{
    this.Close();
}

// The Round over panel's Back to the map button
private void btnDone_Click(object sender, EventArgs e)
{
    this.Close();
}

// Runs as the window closes, by Back, by Done or by the X
private void frmKnots_FormClosing(object sender,
    FormClosingEventArgs e)
{
    if (finished) return;    // a finished round closes at once
    DialogResult answer = MessageBox.Show("Leave Knot Pairs? It will "
        + "score nothing, but you can come back and climb it again.",
        "Summit Ready", MessageBoxButtons.YesNo);
    if (answer == DialogResult.No) e.Cancel = true;   // stay
}

// Shows the speaker picture that matches the sound being on or off
private void ShowSpeaker()
{
    string icon = "icon-speaker-on-64.png";
    if (Sound.Muted) icon = "icon-speaker-muted-64.png";
    picSound.Image = Files.Picture("Icons", icon);
}

// The speaker picture turns the sound off, or back on
private void picSound_Click(object sender, EventArgs e)
{
    Sound.Muted = !Sound.Muted;
    ShowSpeaker();
}

// Turns card i face down: the rope picture on lough blue
private void ShowBack(int i)
{
    cards[i].BackColor = Color.FromArgb(47, 111, 143);
    cards[i].BackgroundImage = rope;
    cards[i].Text = "";
}

// Turns card i face up: its knot's photo, or its knot's name
private void ShowFace(int i)
{
    cards[i].BackColor = Color.White;
    if (isPicture[i])
    {
        cards[i].BackgroundImage = photos[knotOf[i]];
        cards[i].Text = "";
    }
    else
    {
        cards[i].BackgroundImage = null;
        cards[i].Text = knots[knotOf[i]].Name;
    }
}

// Makes card number i: a square button in its row and column
private Button MakeCard(int i)
{
    Button card = new Button();
    card.Size = new Size(140, 140);
    card.Location = new Point(24 + (i % 4) * 148,
        10 + (i / 4) * 148);
    card.FlatStyle = FlatStyle.Flat;
    card.BackgroundImageLayout = ImageLayout.Zoom;
    card.Font = new Font("Segoe UI Semibold", 12);
    card.Click += Card_Click;      // every card runs Card_Click
    pnlPlay.Controls.Add(card);    // put the card on the play area
    return card;
}

// Makes the 16 cards, two for each knot, in a random order
private void MakeCards()
{
    int[] order = Mix.ShuffledNumbers(16);   // 0 to 15, mixed up
    for (int i = 0; i < 16; i++)
    {
        knotOf[i] = order[i] % 8;      // 8 to 15 become 0 to 7 again
        isPicture[i] = order[i] < 8;   // 0 to 7 show the photo
        cards[i] = MakeCard(i);
        ShowBack(i);
    }
}

private void frmKnots_Load(object sender, EventArgs e)
{
    // Runs once, right before the window first appears
    ShowSpeaker();                 // the speaker picture, on or muted
    knots = Knot.LoadAll();
    if (knots.Count < 8)
    {
        lblUse.Text = "Knot Pairs needs 8 knots in Data\\knots.txt. "
            + "Check that the file has 8 lines, each with 3 parts.";
        return;
    }
    rope = Files.Picture("Icons", "icon-rope-128.png");
    for (int k = 0; k < 8; k++)
    {
        photos[k] = Files.Picture("Knots", knots[k].Picture);
    }
    MakeCards();
}

// Finds the number, 0 to 15, of the card that was clicked
private int CardNumber(object sender)
{
    Button clicked = (Button)sender;   // the card that was clicked
    int number = 0;
    for (int c = 0; c < 16; c++)
    {
        if (cards[c] == clicked) number = c;   // found it
    }
    return number;
}

// Runs when any of the 16 cards is clicked
private void Card_Click(object sender, EventArgs e)
{
    int i = CardNumber(sender);
    if (locked || finished || matched[i] || i == first) return;
    ShowFace(i);
    Sound.Play("flip.wav");
    if (first == -1)
    {
        first = i;    // the first card of this try: wait for another
        return;
    }
    tries++;
    lblTries.Text = "Tries: " + tries + " of " + maxTries;
    prgRope.Value = maxTries - tries;
    if (knotOf[first] == knotOf[i]) Match(i);
    else NoMatch(i);
}

// The two cards show the same knot: both stay face up
private void Match(int i)
{
    Color moss = Color.FromArgb(62, 142, 65);
    matched[first] = true;
    matched[i] = true;
    cards[first].FlatAppearance.BorderColor = moss;
    cards[first].FlatAppearance.BorderSize = 4;
    cards[i].FlatAppearance.BorderColor = moss;
    cards[i].FlatAppearance.BorderSize = 4;
    first = -1;
    pairs++;
    lblPairs.Text = "Pairs found: " + pairs + " of 8";
    lblScore.Text = "Points: " + pairs * 10;
    Knot k = knots[knotOf[i]];
    lblUse.Text = k.Name + ": " + k.Use.ToLower();
    Sound.Play("match.wav");
    if (pairs == 8) AllMatched();
    else if (tries == maxTries) RopeSnaps();
}

// The two cards are different knots: show them, then turn them back
private void NoMatch(int i)
{
    Sound.Play("wrong.wav");
    second = i;
    locked = true;          // no clicks count while the pair shows
    tmrFlipBack.Start();    // its Tick runs in 0.9 seconds
}

// Runs 0.9 seconds after a wrong try: both cards turn back over
private void tmrFlipBack_Tick(object sender, EventArgs e)
{
    tmrFlipBack.Stop();     // stop it, or it ticks again
    ShowBack(first);
    ShowBack(second);
    first = -1;
    second = -1;
    locked = false;
    if (tries == maxTries) RopeSnaps();
}

// Every try is used up: the rope snaps
private void RopeSnaps()
{
    lblTries.Text = "The rope snapped!";
    lblTries.ForeColor = Color.FromArgb(178, 58, 46);
    Sound.Play("lose.wav");
    for (int i = 0; i < 16; i++)
    {
        if (matched[i]) continue;   // matched cards stay as they are
        ShowFace(i);
        if (isPicture[i]) AddNameStrip(i);
    }
    lblUse.Text = "Every knot you did not match is now face up with "
        + "its name. Study them, then press See my score.";
    RecordResult();
    btnScore.Visible = true;
}

// Puts the knot's name in a dark strip along the bottom of card i
private void AddNameStrip(int i)
{
    Label strip = new Label();
    strip.Text = knots[knotOf[i]].Name;
    strip.Dock = DockStyle.Bottom;
    strip.Height = 28;
    strip.BackColor = Color.FromArgb(38, 50, 56);
    strip.ForeColor = Color.White;
    strip.TextAlign = ContentAlignment.MiddleCenter;
    cards[i].Controls.Add(strip);
}

// Works out the score, adds the feedback, then keeps the result
private void RecordResult()
{
    int bonus = 0;
    if (pairs == 8 && tries <= 12) bonus = 20;
    else if (pairs == 8 && tries <= 16) bonus = 10;
    result = new GameResult("Knot Pairs", pairs * 10 + bonus);
    AddFeedback();
    KeepResult();
}

// Writes what went well and what went wrong into the result
private void AddFeedback()
{
    if (pairs == 8)
    {
        result.WentWell.Add("You matched them all in " + tries
            + " tries.");
    }
    for (int k = 0; k < 8; k++)
    {
        if (KnotMatched(k))
        {
            result.WentWell.Add("You matched the "
                + knots[k].Name + ".");
        }
        else
        {
            result.WentWrong.Add("You did not match the "
                + knots[k].Name + ".");
        }
    }
    if (pairs == 8 && tries > 12)
    {
        result.WentWrong.Add("You took " + tries + " tries. Twelve "
            + "or fewer earns the full bonus.");
    }
}

// True when the two cards of knot k have been matched
private bool KnotMatched(int k)
{
    for (int i = 0; i < 16; i++)
    {
        if (knotOf[i] == k && matched[i]) return true;
    }
    return false;
}

// All 8 pairs are found: keep the result, then wait 1.2 seconds
private void AllMatched()
{
    RecordResult();
    tmrDone.Start();        // its Tick runs in 1.2 seconds
}

// Runs 1.2 seconds after the last pair: the Round over panel opens
private void tmrDone_Tick(object sender, EventArgs e)
{
    tmrDone.Stop();
    ShowRoundOver();
}

// The button that shows after the rope snaps
private void btnScore_Click(object sender, EventArgs e)
{
    ShowRoundOver();
}
